ARRIVAL_PATTERNS = [
    r"到岗时间[：:\s]*([^\n；;。]{1,40})",
    r"(尽快到岗|尽快|ASAP|asap|可立即到岗|立即到岗|马上到岗|一周内到岗|本周内到岗|下周到岗)",
    r"(\d{1,2}[./月]\d{1,2}(?:日)?(?:/\d{1,2}[./月]\d{1,2}(?:日)?)?到岗)",
]

ROLE_PATTERNS = [
    r"岗位名称[：:\s]*([^\n；;。]{1,60})",
    r"岗位[：:\s]*([^\n；;。]{1,60})",
    r"职位名称[：:\s]*([^\n；;。]{1,60})",
    r"职位[：:\s]*([^\n；;。]{1,60})",
]

EMAIL_PATTERN = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
WECHAT_PATTERN = re.compile(r"(?:微信|vx|Vx|VX|wechat)", flags=re.IGNORECASE)


def default_output_dir() -> Path:
    return Path.cwd() / "output" / "xiaohongshu-relay-scrape"


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Post-process Xiaohongshu scrape results into deduped JSON/CSV/XLSX files.")
    parser.add_argument(
        "--input-json",
        default=str(default_output_dir() / "xiaohongshu_notes_latest.json"),
        help="Path to the raw latest JSON generated by scrape_xiaohongshu_search.py",
    )
    parser.add_argument(
        "--output-dir",
        default=str(default_output_dir()),
        help="Directory for deduped exports and Excel workbooks.",
    )
    return parser.parse_args()


def load_records(path: Path) -> list[dict]:
    return json.loads(path.read_text(encoding="utf-8"))


def dedupe_records(records: list[dict]) -> list[dict]:
    seen: dict[str, dict] = {}
    for record in records:
        key = record.get("note_id") or record.get("note_url") or json.dumps(record, ensure_ascii=False)
        if key not in seen:
            seen[key] = record
    return list(seen.values())


def write_json(path: Path, payload: list[dict]) -> None:
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


def all_fieldnames(rows: list[dict]) -> list[str]:
    fieldnames: list[str] = []
    seen_fields: set[str] = set()
    for row in rows:
        for field in row:
            if field not in seen_fields:
                seen_fields.add(field)
                fieldnames.append(field)
    return fieldnames


def write_csv(path: Path, rows: list[dict]) -> None:
    if not rows:
        path.write_text("", encoding="utf-8")
        return
    fieldnames = all_fieldnames(rows)
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def spreadsheet_value(value):
    if value is None:
        return ""
    if isinstance(value, (dict, list, tuple, set)):
        value = json.dumps(value, ensure_ascii=False, default=str)
    if isinstance(value, str):
        value = ILLEGAL_CHARACTERS_RE.sub("", value)
        if value.startswith(("=", "+", "-", "@")):
            value = f"'{value}"
    return value


def first_match(patterns: list[str], text: str) -> str:
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            return match.group(1).strip()
    return ""


def extract_emails(text: str) -> str:
    emails: list[str] = []
    for email in EMAIL_PATTERN.findall(text):
        if email not in emails:
            emails.append(email)
    return "; ".join(emails)


def detect_delivery_methods(record: dict) -> str:
    text = "\n".join(
        [
            record.get("title", ""),
            record.get("body", ""),
            record.get("source_card_text", ""),
            record.get("card_text_segments", ""),
        ]
    )
    methods: list[str] = []
    if extract_emails(text):
        methods.append("邮箱")
    if any(keyword in text for keyword in ("私信", "私我", "私戳", "私聊", "戳我", "滴我", "联系我", "私发")):
        methods.append("私信")
    if any(keyword in text for keyword in ("评论区", "评论", "留言")):
        methods.append("评论区")
    if WECHAT_PATTERN.search(text):
        methods.append("微信")
    if any(keyword.lower() in text.lower() for keyword in ("boss", "直聘")):
        methods.append("Boss直聘")
    if any(keyword in text for keyword in ("表单", "问卷", "链接投递")):
        methods.append("表单/链接")
    return " | ".join(dict.fromkeys(methods))


def extract_delivery_contact(record: dict) -> str:
    text = "\n".join(
        [
            record.get("title", ""),
            record.get("body", ""),
            record.get("source_card_text", ""),
            record.get("card_text_segments", ""),
        ]
    )
    parts: list[str] = []
    emails = extract_emails(text)
    if emails:
        parts.append(emails)
    if any(keyword in text for keyword in ("私信", "私我", "私戳", "私聊", "戳我", "滴我", "联系我", "私发")):
        parts.append("私信联系")
    if any(keyword in text for keyword in ("评论区", "评论", "留言")):
        parts.append("评论区/留言")
    if WECHAT_PATTERN.search(text):
        parts.append("含微信线索")
    if any(keyword.lower() in text.lower() for keyword in ("boss", "直聘")):
        parts.append("Boss/直聘")
    if any(keyword in text for keyword in ("表单", "问卷", "链接投递")):
        parts.append("表单/链接")
    return " | ".join(dict.fromkeys(parts))


def normalize_company(raw: str) -> str:
    lowered = raw.lower()
    for keyword in COMPANY_KEYWORDS:
        if keyword.lower() in lowered:
            return "小红书" if keyword.lower() == "xhs" else keyword
    return ""


def extract_city_from_text(text: str) -> str:
    for city in CITY_KEYWORDS:
        if city in text:
            return city
    return ""


def extract_city(record: dict) -> str:
    body = record.get("body", "")
    location_match = re.search(r"(?:工作地点|地点|base)[：:\s]*([^\n#]{1,80})", body, flags=re.IGNORECASE)
    if location_match:
        city = extract_city_from_text(location_match.group(1))
        if city:
            return city

    publish_time = record.get("publish_time", "")
    parts = publish_time.split()
    if parts:
        city = extract_city_from_text(parts[-1])
        if city:
            return city

    combined = " ".join(
        [
            record.get("title", ""),
            record.get("source_card_text", ""),
            body,
            record.get("tags", ""),
        ]
    )
    return extract_city_from_text(combined)


def strip_location(raw_time: str) -> str:
    parts = raw_time.strip().split()
    if not parts:
        return raw_time.strip()
    if extract_city_from_text(parts[-1]):
        return " ".join(parts[:-1]).strip()
    return raw_time.strip()


def estimate_publish_time(record: dict) -> str:
    raw_time = strip_location(record.get("publish_time", "").replace("编辑于 ", "").strip())
    scraped_at = record.get("scraped_at", "")
    if not raw_time or not scraped_at:
        return ""

    try:
        base_time = datetime.fromisoformat(scraped_at)
    except ValueError:
        return ""

    minute_match = re.search(r"(\d+)\s*分钟前", raw_time)
    if minute_match:
        return (base_time - timedelta(minutes=int(minute_match.group(1)))).strftime("%Y-%m-%d %H:%M")

    hour_match = re.search(r"(\d+)\s*小时前", raw_time)
    if hour_match:
        return (base_time - timedelta(hours=int(hour_match.group(1)))).strftime("%Y-%m-%d %H:%M")

    day_match = re.search(r"(\d+)\s*天前", raw_time)
    if day_match:
        return (base_time - timedelta(days=int(day_match.group(1)))).strftime("%Y-%m-%d %H:%M")

    yesterday_match = re.search(r"昨天\s*(\d{1,2}:\d{2})", raw_time)
    if yesterday_match:
        return f"{(base_time - timedelta(days=1)).strftime('%Y-%m-%d')} {yesterday_match.group(1)}"

    full_date_match = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}:\d{2}))?", raw_time)
    if full_date_match:
        hhmm = full_date_match.group(4) or "00:00"
        return (
            f"{full_date_match.group(1)}-"
            f"{int(full_date_match.group(2)):02d}-"
            f"{int(full_date_match.group(3)):02d} {hhmm}"
        )

    mmdd_match = re.fullmatch(r"(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}:\d{2}))?", raw_time)
    if mmdd_match:
        hhmm = mmdd_match.group(3) or "00:00"
        return f"{base_time.year}-{int(mmdd_match.group(1)):02d}-{int(mmdd_match.group(2)):02d} {hhmm}"

    return ""


def extract_role(record: dict) -> str:
    body = record.get("body", "")
    title = record.get("title", "")
    combined = "\n".join([title, body])

    role = first_match(ROLE_PATTERNS, combined)
    if role:
        return role

    title_match = re.search(r"([^\n，。；;]{2,40}(?:运营|产品|内容|商业化|采销|咨询|增长|电商)[^\n，。；;]{0,20}实习(?:生)?)", combined)
    if title_match:
        return title_match.group(1).strip()

    fallback_match = re.search(r"([^\n，。；;]{2,40}实习(?:继任|生)?)", title)
    if fallback_match:
        return fallback_match.group(1).strip()

    return ""


def extract_arrival(record: dict) -> str:
    text = "\n".join([record.get("title", ""), record.get("body", ""), record.get("source_card_text", "")])
    return first_match(ARRIVAL_PATTERNS, text)


def body_excerpt(text: str, limit: int = 220) -> str:
    return re.sub(r"\s+", " ", text).strip()[:limit]


def as_text(value: object) -> str:
    """Normalize checkpoint fields before text extraction and workbook writes."""
    if value is None:
        return ""
    if isinstance(value, (list, tuple, set)):
        return " ".join(as_text(item) for item in value)
    if isinstance(value, dict):
        return json.dumps(value, ensure_ascii=False, sort_keys=True)
    return str(value)


def build_structured_rows(records: list[dict]) -> list[dict]:
    rows: list[dict] = []
    for record in records:
        combined_text = " ".join(
            [
                as_text(record.get("title", "")),
                as_text(record.get("body", "")),
                as_text(record.get("source_card_text", "")),
                as_text(record.get("tags", "")),
                as_text(record.get("card_title", "")),
                as_text(record.get("card_tags", "")),
                as_text(record.get("card_badges", "")),
                as_text(record.get("card_text_segments", "")),
            ]
        )
        rows.append(
            {
                "笔记ID": record.get("note_id", ""),
                "访问层级": record.get("access_level", ""),
                "访问状态": record.get("access_status", ""),
                "搜索结果页": record.get("source_search_url", ""),
                "卡片排名": record.get("card_rank", ""),
                "标题": record.get("title", ""),
                "作者": record.get("author", ""),
                "发布时间": record.get("publish_time", ""),
                "发布时间(估算)": estimate_publish_time(record),
                "城市": extract_city(record),
                "公司/平台": normalize_company(combined_text),
                "岗位": extract_role(record),
                "到岗时间": extract_arrival(record),
                "投递方式": detect_delivery_methods(record),
                "联系方式": extract_delivery_contact(record),
                "邮箱": extract_emails(record.get("body", "")),
                "点赞": record.get("like_count", ""),
                "收藏": record.get("collect_count", ""),
                "评论": record.get("comment_count", ""),
                "标签": record.get("tags", ""),
                "笔记链接": record.get("note_url", ""),
                "作者主页": record.get("author_profile", ""),
                "卡片标题": record.get("card_title", ""),
                "卡片作者": record.get("card_author", ""),
                "卡片作者主页": record.get("card_author_profile", ""),
                "卡片发布时间": record.get("card_publish_time", ""),
                "卡片点赞": record.get("card_like_count", ""),
                "卡片收藏": record.get("card_collect_count", ""),
                "卡片评论": record.get("card_comment_count", ""),
                "卡片封面": record.get("card_cover_url", ""),
                "卡片封面Alt": record.get("card_cover_alt", ""),
                "卡片标签": record.get("card_tags", ""),
                "卡片徽标": record.get("card_badges", ""),
                "卡片搜索链接": record.get("card_search_result_url", ""),
                "卡片详情链接": record.get("card_explore_url", ""),
                "卡片链接URLs": record.get("card_link_urls", ""),
                "卡片图片URLs": record.get("card_image_urls", ""),
                "卡片文本片段": record.get("card_text_segments", ""),
                "卡片摘要": record.get("source_card_text", ""),
                "正文摘要": body_excerpt(record.get("body", "")),
                "正文": record.get("body", ""),
            }
        )
    return rows


def write_sheet(ws, headers: list[str], rows: list[dict], width_map: dict[str, float]) -> None:
    for col_idx, header in enumerate(headers, start=1):
        cell = ws.cell(row=1, column=col_idx, value=header)
        cell.fill = HEADER_FILL
        cell.font = HEADER_FONT
        cell.alignment = WRAP_TOP

    for row_idx, row in enumerate(rows, start=2):
        for col_idx, header in enumerate(headers, start=1):
            value = row.get(header, "")
            cell = ws.cell(row=row_idx, column=col_idx, value=spreadsheet_value(value))
            cell.alignment = WRAP_TOP
            if header in {"笔记链接", "作者主页"} and value:
                cell.hyperlink = value
                cell.font = LINK_FONT

    for col_idx, header in enumerate(headers, start=1):
        ws.column_dimensions[get_column_letter(col_idx)].width = width_map.get(header, 18)

    ws.freeze_panes = "A2"
    ws.auto_filter.ref = ws.dimensions
    for row_idx in range(2, ws.max_row + 1):
        ws.row_dimensions[row_idx].height = 48


def write_dedup_workbook(records: list[dict], output_path: Path, source_json: Path) -> None:
    workbook = Workbook()
    summary = workbook.active
    summary.title = "Summary"
    raw = workbook.create_sheet("Raw")

    summary_rows = [
        ("项目", "值"),
        ("导出时间", datetime.now().strftime("%Y-%m-%d %H:%M:%S")),
        ("唯一笔记数", len(records)),
        ("来源 JSON", str(source_json)),
    ]
    for row_idx, row in enumerate(summary_rows, start=1):
        for col_idx, value in enumerate(row, start=1):
            cell = summary.cell(row=row_idx, column=col_idx, value=value)
            cell.alignment = WRAP_TOP
            if row_idx == 1:
                cell.fill = HEADER_FILL
                cell.font = HEADER_FONT
            elif col_idx == 1:
                cell.fill = SECTION_FILL
                cell.font = Font(bold=True)
    summary.column_dimensions["A"].width = 18
    summary.column_dimensions["B"].width = 100
    summary.freeze_panes = "A2"

    raw_headers = all_fieldnames(records)
    raw_rows = [{key: record.get(key, "") for key in raw_headers} for record in records]
    raw_widths = {
        "note_id": 18,
        "title": 34,
        "author": 18,
        "author_profile": 45,
        "note_url": 45,
        "publish_time": 20,
        "like_count": 10,
        "collect_count": 10,
        "comment_count": 10,
        "body": 120,
        "body_html": 140,
        "tags": 34,
        "source_card_text": 42,
        "scraped_at": 20,
    }
    write_sheet(raw, raw_headers, raw_rows, raw_widths)
    workbook.save(output_path)


def write_structured_workbook(records: list[dict], output_path: Path, source_json: Path) -> None:
    structured_rows = build_structured_rows(records)
    workbook = Workbook()
    summary = workbook.active
    summary.title = "Summary"
    structured = workbook.create_sheet("Structured")
    raw = workbook.create_sheet("Raw")

    summary_rows = [
        ("项目", "值"),
        ("导出时间", datetime.now().strftime("%Y-%m-%d %H:%M:%S")),
        ("唯一笔记数", len(records)),
        ("说明", "Structured 适合投递筛选；Raw 保留完整原始字段"),
        ("来源 JSON", str(source_json)),
    ]
    for row_idx, row in enumerate(summary_rows, start=1):
        for col_idx, value in enumerate(row, start=1):
            cell = summary.cell(row=row_idx, column=col_idx, value=value)
            cell.alignment = WRAP_TOP
            if row_idx == 1:
                cell.fill = HEADER_FILL
                cell.font = HEADER_FONT
            elif col_idx == 1:
                cell.fill = SECTION_FILL
                cell.font = Font(bold=True)
    summary.column_dimensions["A"].width = 18
    summary.column_dimensions["B"].width = 110
    summary.freeze_panes = "A2"

    structured_headers = list(structured_rows[0].keys()) if structured_rows else []
    structured_widths = {
        "笔记ID": 18,
        "标题": 34,
        "作者": 18,
        "发布时间": 20,
        "发布时间(估算)": 20,
        "城市": 12,
        "公司/平台": 16,
        "岗位": 28,
        "到岗时间": 18,
        "投递方式": 18,
        "联系方式": 34,
        "邮箱": 34,
        "点赞": 10,
        "收藏": 10,
        "评论": 10,
        "标签": 34,
        "笔记链接": 45,
        "作者主页": 45,
        "卡片摘要": 42,
        "正文摘要": 60,
        "正文": 120,
    }
    write_sheet(structured, structured_headers, structured_rows, structured_widths)

    raw_headers = all_fieldnames(records)
    raw_rows = [{key: record.get(key, "") for key in raw_headers} for record in records]
    raw_widths = {
        "note_id": 18,
        "title": 34,
        "author": 18,
        "author_profile": 45,
        "note_url": 45,
        "publish_time": 20,
        "like_count": 10,
        "collect_count": 10,
        "comment_count": 10,
        "body": 120,
        "body_html": 140,
        "tags": 34,
        "source_card_text": 42,
        "scraped_at": 20,
    }
    write_sheet(raw, raw_headers, raw_rows, raw_widths)
    workbook.save(output_path)


def main() -> None:
    args = parse_args()
    source_json = Path(args.input_json).resolve()
    output_dir = Path(args.output_dir).resolve()
    output_dir.mkdir(parents=True, exist_ok=True)

    raw_records = load_records(source_json)
    deduped_records = dedupe_records(raw_records)

    dedup_json = output_dir / "xiaohongshu_notes_latest_dedup.json"
    dedup_csv = output_dir / "xiaohongshu_notes_latest_dedup.csv"
    dedup_xlsx = output_dir / "xiaohongshu_notes_latest_dedup.xlsx"
    structured_xlsx = output_dir / "xiaohongshu_notes_structured.xlsx"
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

    write_json(dedup_json, deduped_records)
    write_csv(dedup_csv, deduped_records)
    write_dedup_workbook(deduped_records, dedup_xlsx, source_json)
    write_structured_workbook(deduped_records, structured_xlsx, dedup_json)

    write_json(output_dir / f"xiaohongshu_notes_{timestamp}_dedup.json", deduped_records)
    write_csv(output_dir / f"xiaohongshu_notes_{timestamp}_dedup.csv", deduped_records)
    write_dedup_workbook(deduped_records, output_dir / f"xiaohongshu_notes_{timestamp}_dedup.xlsx", source_json)
    write_structured_workbook(deduped_records, output_dir / f"xiaohongshu_notes_structured_{timestamp}.xlsx", dedup_json)

    print(dedup_json)
    print(dedup_csv)
    print(dedup_xlsx)
    print(structured_xlsx)


if __name__ == "__main__":
    main()
